import {controller, target} from '@github/catalyst'

@controller('credential-revocation-dialog')
export class CredentialRevocationDialogElement extends HTMLElement {
  @target declare hiddenInput: HTMLInputElement
  @target declare selectError: HTMLElement
  @target declare detailsSection: HTMLElement
  @target declare verifyInput: HTMLInputElement
  @target declare verifyError: HTMLElement
  @target declare triggerButton: HTMLElement

  #handleItemActivated = (event: Event) => {
    const detail = (event as CustomEvent).detail
    if (!detail?.item) return

    const item = detail.item as HTMLElement
    const value = detail.value || item.textContent?.trim() || ''
    this.hiddenInput.value = value
    this.selectError.hidden = true

    // Extract display name and inject into details text
    const labelEl = item.querySelector('.ActionListItem-label')
    const displayName = labelEl ? labelEl.textContent?.trim() || value : value

    const nameSpan = this.detailsSection.querySelector('.js-selected-display-name')
    if (nameSpan) nameSpan.textContent = displayName
    this.detailsSection.hidden = false

    // Clone avatar into trigger button
    const itemAvatar = item.querySelector('img')
    if (itemAvatar && this.triggerButton) {
      const label = this.triggerButton.querySelector('.Button-label')
      if (label?.parentElement) {
        const prev = this.triggerButton.querySelector('.js-selected-avatar')
        if (prev) prev.remove()

        const img = document.createElement('img')
        img.src = itemAvatar.src
        img.alt = ''
        img.width = 20
        img.height = 20
        img.className = 'avatar avatar-small circle mr-2 js-selected-avatar'
        img.setAttribute('aria-hidden', 'true')
        label.parentElement.insertBefore(img, label)
      }
    }
  }

  validate(event: Event) {
    const userSelected = this.hiddenInput.value.length > 0
    const slug = (this.getAttribute('data-slug') || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const pattern = new RegExp(`^${slug} credentials$`, 'i')
    const verifyValid = pattern.test(this.verifyInput.value)

    if (!userSelected || !verifyValid) {
      event.preventDefault()
      this.selectError.hidden = userSelected

      const showVerifyError = userSelected && !verifyValid
      this.verifyError.hidden = !showVerifyError
      if (showVerifyError) {
        this.verifyInput.classList.add('border-danger')
      } else {
        this.verifyInput.classList.remove('border-danger')
      }
    } else {
      this.selectError.hidden = true
      this.verifyError.hidden = true
      this.verifyInput.classList.remove('border-danger')
    }
  }

  #applyInputStyles() {
    for (const input of this.querySelectorAll<HTMLElement>('.FormControl-input')) {
      input.style.width = '100%'
      input.style.maxWidth = '100%'
    }
  }

  connectedCallback() {
    this.addEventListener('itemActivated', this.#handleItemActivated, true)

    // Ensure SelectPanel search inputs use full width
    this.#applyInputStyles()
  }

  disconnectedCallback() {
    this.removeEventListener('itemActivated', this.#handleItemActivated, true)
  }
}
